# -*- coding: utf-8 -*-
from sm1 import S, C

PART3 = [

C("People & Recruiting","Finding, developing and keeping the right people",
"Every ceiling a church hits is eventually a leadership ceiling, and leadership is produced rather than found.",
["Who invited you into ministry?","What is the best team you built?","Who are you investing in right now?","What made you say yes the first time?"],
["Father, send us workers. Make us the kind of leaders worth following and worth leaving.",
 "Lord, help us see potential where others see availability."],
["Matthew 9:37-38","2 Timothy 2:2","Acts 13:1-3","Exodus 18:21","Ephesians 4:11-13"],
"Bring actual names. This category collapses into generalities without them, and generalities produce no follow-through.",
[S("Who Is Missing","The seat nobody has filled",["Acts 6:1-4","Nehemiah 7:1-2","Matthew 9:36-38"],["The complaint in Acts 6 was real and the answer was structural","Nehemiah appointed because a job existed","Pray for workers before you post a job"],"Lord of the harvest, send workers.",["Write the role description for the gap","Ask whether a volunteer could do it","Pray for a name this week"]),
 S("The Personal Ask","Why announcements do not work",["John 1:40-42","Luke 5:27","Mark 1:16-18"],["Almost nobody started serving because of an announcement","Andrew found his brother first","Follow me was said to a face"],"Father, give us courage to ask by name.",["Ask three people personally","Name them out loud here","Follow up within a week"]),
 S("Apprentices","Building the next leader in from week one",["2 Timothy 2:2","Mark 3:14","1 Kings 19:19-21"],["If nobody is learning your job you have built a ceiling","He appointed twelve to be with him","Elijah threw his cloak over Elisha"],"Lord, help us reproduce rather than perform.",["Name one apprentice and tell them","Give them one real thing","Report back next month"]),
 S("Why They Leave","Volunteer retention honestly",["Galatians 6:9","Proverbs 27:23","1 Thessalonians 5:12"],["Most volunteers drift out rather than quit","Know the condition of your flocks","Acknowledge those who work hard among you"],"Father, help us notice before it is too late.",["Call one person who stopped","Ask why, and listen","Fix one thing they name"]),
 S("Screening Without Insulting","Safety as care",["Nehemiah 7:2","1 Timothy 3:10","Proverbs 22:3"],["Screening framed as suspicion offends; framed as protection it reassures","Let them first be tested","The prudent see danger and take refuge"],"Lord, help us protect the vulnerable well.",["Review one screening process","Rewrite how it is explained","Close one gap this month"]),
 S("The First Ninety Days","Onboarding staff and volunteers",["Joshua 1:1-9","Acts 9:26-28","Deuteronomy 31:7-8"],["Churches recruit well and onboard badly, then blame the person","Barnabas took Saul and vouched for him","Be strong and courageous was said repeatedly"],"Father, help us set people up to succeed.",["Write a ninety-day onboarding plan","Assign one buddy","Ask the newest person what was missing"]),
 S("Developing Rather Than Using","The difference people feel",["Ephesians 4:11-12","Luke 6:40","Colossians 1:28-29"],["There is a difference between deploying and developing and people can tell","A student fully trained becomes like the teacher","We labour to present everyone mature"],"Lord, help us grow people rather than fill slots.",["Ask one volunteer what they want to learn","Invest one hour in them","Follow up next month"]),
 S("The Difficult Volunteer","The conversation nobody wants",["Acts 15:37-39","Proverbs 27:5","Romans 12:3"],["Leaving someone in the wrong seat is kindness to our discomfort","Paul and Barnabas disagreed sharply and both works continued","Think of yourself with sober judgement"],"Father, give us honesty wrapped in love.",["Have one repositioning conversation","Offer a better fit rather than an exit","Pray for them by name first"]),
 S("Recruiting Season","Rhythm rather than emergency",["Ecclesiastes 3:1-2","Proverbs 6:6-8","John 4:35"],["Recruiting when desperate produces people who match your desperation","The ant stores in summer","Look at the fields, they are ripe"],"Lord, give us foresight rather than panic.",["Put two recruiting seasons on the calendar","Start asking eight weeks early","Name the target number"]),
 S("Give Them Away","Sending your best",["Acts 13:1-3","2 Timothy 2:2","Philippians 2:19-22"],["Antioch sent its two best and we got most of the New Testament","Sending is multiplication, keeping is addition","Paul had no one else like Timothy and sent him anyway"],"Father, hold us loosely to our best people.",["Tell one person you are preparing them","Name where they might go","Start the conversation with their supervisor"])]),

C("Communication & Conflict","Saying it well and repairing it fast",
"Most church conflict is not doctrinal. It is a message somebody received differently from how it was sent.",
["What is the best communication you ever received?","What is a phrase you overuse?","How do you prefer to be told bad news?","Text, call or in person?"],
["Lord, guard our tongues and soften our hearts. Let us speak the truth in love and repair quickly.",
 "Father, make us quick to listen, slow to speak and slow to become angry."],
["James 1:19-20","Ephesians 4:25-32","Proverbs 15:1","Matthew 18:15-17","Colossians 4:6"],
"If there is a live conflict on the team, do not run these as a proxy. Name the pattern, handle the specific privately.",
[S("Announce Less","The attention budget",["Proverbs 10:19","Ecclesiastes 5:2","Matthew 6:7"],["Every extra announcement reduces the impact of all the others","Many words, much sin","Do not heap up empty phrases"],"Lord, help us say less and mean more.",["Cut your next request in half","Count last Sunday's announcements","Choose the one that matters"]),
 S("One Message, Seven Ways","Repetition as respect",["Habakkuk 2:2","Deuteronomy 6:6-9","2 Peter 1:12-13"],["Saying it once from the platform is a broadcast, not communication","Write it plainly on tablets","I will always remind you, even though you know"],"Father, make us patient repeaters.",["Carry one message through three channels","Name who never hears anything","Ask how people actually find out"]),
 S("The Difficult Email","When to stop typing",["Proverbs 15:1","James 3:5-6","Proverbs 18:13"],["Anything requiring tone should not be sent in a medium that has none","A gentle answer turns away wrath","Answering before listening is folly"],"Lord, keep us from writing what we should say.",["Convert one email to a conversation","Adopt the two-reply rule","Delete one draft"]),
 S("Listening","The half we skip",["James 1:19","Proverbs 18:2","Job 2:11-13"],["Most of us listen for the gap where we can start talking","A fool delights in airing his own opinion","Job's friends sat seven days and said nothing"],"Father, teach us to listen without preparing a reply.",["Ask one question and stay silent two minutes","Listen to someone you usually discount","Repeat back what you heard"]),
 S("Repair Fast","The forty-eight hour rule",["Matthew 5:23-24","Ephesians 4:26","Romans 12:18"],["Jesus put reconciliation ahead of worship and we quietly reversed it","Do not let the sun go down on your anger","So far as it depends on you, live at peace"],"Lord, make us quick to repair.",["Make one repair move in forty-eight hours","Go first even if you are not wrong","Ask what you contributed"]),
 S("The Critic","Handling criticism well",["Proverbs 15:31-32","1 Corinthians 4:3-4","Proverbs 9:8"],["We discard the true part along with the unfair part","Whoever heeds correction gains understanding","Rebuke the wise and they will love you"],"Father, help us receive what is true.",["Extract one true thing from recent criticism","Thank the person","Ask someone to help you sort it"]),
 S("Gossip","The sin with no support group",["Proverbs 16:28","Proverbs 26:20","Ephesians 4:29"],["Gossip is usually unmet need for information filled badly","Without wood a fire goes out","Only what is helpful for building others up"],"Lord, guard what we say about people who are not here.",["Redirect one conversation to the person","Admit where you have participated","Ask for information rather than speculate"]),
 S("Bad News","Delivering it well",["2 Samuel 12:1-13","Proverbs 25:11","Colossians 4:6"],["Bad news delivered late is worse than bad news delivered badly","A word fittingly spoken is like apples of gold","Let your speech be seasoned with salt"],"Father, give us courage and kindness together.",["Deliver one piece of pending news","Rehearse the opening sentence","Say it in person"]),
 S("What They Actually Heard","The gap between sent and received",["1 Corinthians 14:9","Nehemiah 8:8","Proverbs 18:2"],["The message is what they heard, and checking is our job","They read and gave the meaning so people understood","Assuming understanding is not communicating"],"Lord, help us close the gap.",["Ask three people what they understood","Bring the answers back","Rewrite one thing that failed"]),
 S("Crisis Communication","What to say in the first hour",["Nehemiah 4:14","Proverbs 22:3","Acts 20:28-31"],["Silence is filled by someone else's version within two hours","Do not be afraid, remember the Lord","Be on guard, and warn people"],"Father, give us wisdom under pressure.",["Write the first-hour plan","Name who speaks","Decide what we say before we know things"])]),

C("Seasons & Pressure","The particular weeks that break people",
"The church calendar produces predictable pressure at predictable times, and we act surprised every year.",
["What is your favourite season of the church year?","When are you at your best?","What is your least favourite month and why?","What helps you recover?"],
["Lord, you appointed seasons. Give us wisdom for the hard ones and gratitude in the full ones.",
 "Father, carry us through what we cannot carry ourselves."],
["Ecclesiastes 3:1-8","1 Kings 19:1-9","Mark 6:30-32","Psalm 121","Isaiah 43:1-3"],
"Run these before the season, not during it. In December a session about December is too late to be useful.",
[S("Before Christmas","Protecting December",["Mark 6:31","Ecclesiastes 3:1","Exodus 18:18"],["December is hard by design and the design is ours","Come away and rest a while","You will surely wear yourself out"],"Lord, protect us in the busiest month.",["Remove one thing from December","Name who carries the most","Schedule recovery in January"]),
 S("After Easter","The crash nobody plans for",["1 Kings 19:1-9","Psalm 23:2-3","Matthew 11:28"],["The biggest Sunday is followed by the emptiest week","Elijah wanted to die after his greatest victory","He makes me lie down"],"Father, restore us after we pour out.",["Book recovery the week after","Cancel one meeting","Feed and sleep before evaluating"]),
 S("The Summer Slump","Leading through low attendance",["Ecclesiastes 3:1","Galatians 6:9","Mark 4:26-29"],["Attendance drops everywhere; treating it as failure is a choice","At the proper time we will reap","The seed grows while he sleeps"],"Lord, give us patience in slow seasons.",["Plan one thing summer is good for","Reduce anxiety with the multi-year pattern","Protect team rest"]),
 S("Fall Launch","The second January",["Proverbs 6:6-8","Proverbs 21:5","Nehemiah 2:6"],["The fall is won in July","The ant prepares in summer","Diligent planning leads to profit"],"Father, help us prepare rather than react.",["Set the launch date and owners","Decide everything by August","Review last year's lessons"]),
 S("Budget Season","The most spiritual month nobody calls spiritual",["Luke 14:28","Proverbs 27:23-24","2 Corinthians 8:20-21"],["A budget is a moral document","Sit down and estimate the cost","We take pains to do what is right"],"Lord, let our spending reflect our confession.",["Bring priorities before numbers","Learn the actual timeline","Name one thing to fund and one to stop"]),
 S("When Giving Drops","Leading through a shortfall",["Philippians 4:12","1 Kings 17:8-16","2 Corinthians 8:1-5"],["Silence is read as denial or catastrophe, both worse than truth","The jar of flour was not used up","Poverty overflowed in generosity"],"Father, we trust you with what we do not have.",["Write the shortfall plan now","Decide what is cut first","Tell people early and plainly"]),
 S("The Long Grind","Ordinary time",["Galatians 6:9","1 Corinthians 15:58","Colossians 3:23"],["Most of ministry is February","Let us not grow weary in doing good","Your labour is not in vain"],"Lord, sustain us in the unremarkable months.",["Add one thing to look forward to","Name what erodes your engagement","Celebrate something small"]),
 S("Burnout","Naming it before it arrives",["1 Kings 19:4-8","Exodus 18:17-18","Matthew 11:28-30"],["Burnout is visible for months if anyone is looking","The task is too heavy for you alone","My yoke is easy"],"Father, catch us before we fall.",["Check on one colleague specifically","Name your own warning signs","Give one thing away this week"]),
 S("A Crisis in the Church","When something breaks publicly",["Galatians 6:1-2","1 Corinthians 5:1-5","2 Corinthians 2:5-8"],["Decide how you will handle a crisis a year before it happens","Restore gently, watching yourself","Forgive and comfort so they are not overwhelmed"],"Lord, prepare us for what we hope never comes.",["Draft the crisis protocol","Name who leads","Decide the care plan for everyone affected"]),
 S("Celebrating","The discipline of stopping",["Nehemiah 8:10","Luke 15:22-24","Psalm 126:1-3"],["Teams that do not celebrate develop a permanent not-yet","The joy of the Lord is your strength","Let us celebrate, for this son of mine was lost"],"Father, teach us to stop and rejoice.",["Celebrate one thing publicly","Do it in this meeting","Name what we never celebrated"])]),

C("Multiplication & Legacy","Building past yourself",
"The final test of any leader is not what they built but what continues after they stop touching it.",
["Who is still walking with God because of someone here?","What do you want to be remembered for?","Who mentored you?","What have you handed off well?"],
["Lord, let us build what outlives us. Free us from needing to be necessary.",
 "Father, we are all interim. Help us hand on something healthier than we received."],
["2 Timothy 2:2","Psalm 78:1-7","Acts 13:1-3","Numbers 27:15-20","John 3:30"],
"Requires real trust. Do not run these early in a team's life or during instability.",
[S("What Survives You","The bus question, asked seriously",["2 Timothy 2:2","Acts 20:28-32","Deuteronomy 34:9"],["Indispensability feels like security and measures what you failed to build","Paul commended them to God and the word","Joshua was filled with the spirit of wisdom because Moses had laid hands on him"],"Lord, help us build what does not need us.",["Document one thing only you know","Name what breaks if you leave","Hand one thing over permanently"]),
 S("Four Generations","The measure that matters",["2 Timothy 2:2","Psalm 78:4-7","Judges 2:10"],["Paul names four generations in one verse; most of us cannot name two","Tell the next generation so they tell theirs","Another generation grew up who did not know"],"Father, let this go further than us.",["Draw your chain on paper","Find where it stops","Name the next link"]),
 S("Giving It Away","Releasing what you built",["John 3:30","Philippians 2:5-7","1 Corinthians 3:6-7"],["The hardest thing to release is what you are best at","He must increase, I must decrease","Paul planted, Apollos watered, God gave the growth"],"Lord, loosen our grip.",["Hand over one thing permanently","Stop checking it","Tell the team it is theirs now"]),
 S("Raising Your Replacement","The uncomfortable assignment",["Numbers 27:15-20","2 Kings 2:9-15","1 Kings 19:19-21"],["Moses asked for a successor before he needed one","Elisha asked for a double portion","Commission them in front of everyone"],"Father, give us successors better than us.",["Begin one succession conversation","Name two possible people","Give one of them a real test"]),
 S("The Ceiling Is You","When the leader is the limit",["Exodus 18:18","Acts 6:2-4","2 Corinthians 12:9"],["Every plateau traces to a leader who stopped growing or delegating","The task is too heavy","My power is made perfect in weakness"],"Lord, show us our own limits.",["Name your ceiling out loud","Ask what you must learn or release","Choose one and start"]),
 S("Sending","Multiplication that costs you",["Acts 13:2-3","Matthew 28:19-20","Acts 8:1-4"],["A church that only adds eventually stops","Set apart for me Barnabas and Saul","Those who were scattered preached wherever they went"],"Father, make us a sending church.",["Name one person to send","Start preparing them","Tell the church we intend to"]),
 S("Writing It Down","Systems that outlive people",["Habakkuk 2:2","Luke 1:3-4","Deuteronomy 31:24-26"],["Tribal knowledge is a polite name for a single point of failure","Write it and make it plain","An orderly account so you may know with certainty"],"Lord, help us leave a trail.",["Write one page of process","Put it where people can find it","Ask someone to follow it"]),
 S("The Second Chair","Leading from beside",["1 Samuel 18:1-4","Acts 11:22-26","Exodus 17:12"],["Second chair leadership is a gift churches rarely name","Jonathan gave David his robe","Barnabas went and looked for Saul"],"Father, honour those who lead from beside.",["Honour one second-chair leader publicly","Ask what they need","Give them a decision that is theirs"]),
 S("Twenty Years From Now","Working backward from the end",["Psalm 78:4-7","Isaiah 58:12","Hebrews 11:13"],["Most of this week's list will be irrelevant in twenty years and some will not","You will be called repairer of broken walls","They saw the promises from a distance"],"Lord, give us a long view.",["Name one thing worth twenty years","Start it this quarter","Tell someone who will still be here"]),
 S("Hand It On","The closing session",["2 Timothy 4:6-8","Joshua 24:15","Psalm 71:18"],["We are all interim; the question is what condition we hand on","I have fought the good fight","Declare your power to the next generation"],"Father, let us finish faithful.",["Write a one-page letter to your successor","Name what you would fix first","Seal it and open it in a year"])]),

C("Prayer & Dependence","Learning it by doing it together",
"Every staff meeting opens with prayer and most staff can go a week without praying alone. Both are true and only one is visible.",
["When has God clearly answered a prayer for you?","Where do you pray best?","What do you find hardest about prayer?","Who taught you to pray?"],
["Lord, teach us to pray. Not better words — just more of them, and more honestly.",
 "Father, we depend on you. Forgive us for the weeks we run this church as if we did not."],
["Luke 11:1-13","Matthew 6:5-15","James 5:13-18","Philippians 4:6-7","Ephesians 6:18"],
"Keep the bar low. Ambitious prayer commitments made in a room fail by Wednesday.",
[S("Teach Us to Pray","The one thing they asked for",["Luke 11:1","Matthew 6:9-13","Romans 8:26"],["They watched him do everything and asked to be taught this","He gave a shape rather than a script","The Spirit intercedes when we have no words"],"Lord, teach us to pray.",["Pray the Lord's Prayer slowly this week","Ask God for one thing plainly","Pray with one other person"]),
 S("Praying for Each Other","Not just about the church",["James 5:16","Ephesians 6:18","Colossians 1:9"],["We pray about the church constantly and for each other rarely","Pray for each other so you may be healed","We have not stopped praying for you"],"Father, hold each of us as we hold each other.",["Pray for the person on your left by name","Ask what they actually need","Follow up in a week"]),
 S("Persistence","The friend at midnight",["Luke 11:5-10","Luke 18:1-8","Genesis 32:26"],["Persistence is not a lack of faith; Jesus commends it","Ask, seek, knock are all present tense","I will not let you go unless you bless me"],"Lord, give us the boldness to keep asking.",["Restart something you stopped praying for","Pray it daily for a month","Tell someone you are asking again"]),
 S("Unanswered","When the answer is no or not yet",["2 Corinthians 12:7-10","Psalm 13","Hebrews 11:39-40"],["Paul asked three times and was told no","How long, O Lord is in the book","They did not receive what was promised"],"Father, we trust you with the ones you have not answered.",["Name one unanswered prayer out loud","Keep praying it anyway","Ask someone to carry it with you"]),
 S("Praying Scripture","Borrowing the words",["Psalm 119:105","Colossians 1:9-12","Ephesians 1:16-19"],["Scripture gives us words when ours run out","Paul prayed Scripture back over churches","The Psalms are prayers before they are poems"],"Lord, let your Word shape our asking.",["Pray one psalm each day this week","Pray Colossians 1 over your team","Write one prayer from a passage"]),
 S("Fasting and Prayer Together","The pairing the church dropped",["Matthew 6:16-18","Acts 13:2-3","Ezra 8:21-23"],["Fasting shows what has been running us underneath","They fasted and prayed and then sent","We fasted and petitioned and he answered"],"Father, empty us enough to hear you.",["Fast from one thing this week","Pair it with a specific request","Do it with one other person"]),
 S("Praying for the City","Beyond our own walls",["Jeremiah 29:7","1 Timothy 2:1-2","Nehemiah 1:4-11"],["Seek the welfare of the city and pray to the Lord for it","Pray for all in authority","Nehemiah wept, then prayed, then planned"],"Lord, give us a heart for this place.",["Pray for one street or school","Pray by name for a local leader","Pray-walk one neighbourhood"]),
 S("Listening Prayer","The half we skip",["1 Samuel 3:1-10","1 Kings 19:11-13","Psalm 46:10"],["Speak, for your servant is listening","The Lord was in the gentle whisper","Be still and know"],"Father, quiet us enough to hear.",["Ten silent minutes this week","Write down what surfaces","Test it with someone wise"]),
 S("Praying Before Deciding","Discernment as practice",["Acts 1:24","Acts 13:2","Joshua 9:14"],["They did not inquire of the Lord is the whole verdict on Gibeon","While they were worshipping, the Spirit said","Prayer before a decision, not after"],"Lord, we will not move without you.",["Pray before the next decision","Delay one decision a week","Ask what we skipped praying about"]),
 S("A Praying Staff","Making it more than an opening",["Acts 2:42","Acts 4:23-31","Colossians 4:2"],["An opening prayer is not a praying team","They raised their voices together","Devote yourselves to prayer"],"Father, make us a praying staff rather than a staff that prays.",["Give prayer a real block, not the opening","Pray for one ministry each week","Cancel one agenda item for prayer"])]),

C("The Word & Study","Handling Scripture well",
"We handle the Bible professionally every week. The risk is that it stops being food and becomes material.",
["What passage has shaped you most?","What is the hardest book of the Bible for you?","What is your study routine?","What was the first Bible you owned?"],
["Lord, let your Word be food before it is material. Speak to us before you speak through us.",
 "Father, guard us from handling holy things carelessly."],
["2 Timothy 3:14-17","Psalm 119:9-16","Hebrews 4:12-13","Nehemiah 8:1-8","James 1:22-25"],
"Keep these practical. The temptation is to make them a seminary class; the aim is a staff that reads.",
[S("Food Before Material","Reading for yourself",["Jeremiah 15:16","Psalm 1:2","Matthew 4:4"],["Professional handling replaces personal receiving unless you fight both","His words were found and eaten","Man does not live on bread alone"],"Lord, feed us first.",["Read one chapter with no sermon attached","Pick a book you will not preach","Read at a different time"]),
 S("Context Changes Everything","Reading responsibly",["2 Timothy 2:15","Nehemiah 8:8","Acts 17:11"],["A verse without context can be made to say almost anything","Correctly handling the word of truth","They examined the Scriptures to see if it were so"],"Father, keep us honest with your Word.",["Read one favourite verse in full context","Check one thing you have always assumed","Read a whole letter in one sitting"]),
 S("The Hard Passages","The texts nobody preaches",["2 Timothy 3:16","Psalm 88","Judges 19"],["All Scripture is God-breathed, including the parts we skip","Some texts are meant to disturb","Avoiding them teaches the congregation to avoid them"],"Lord, give us courage with the difficult texts.",["Read one passage you avoid","Name why you avoid it","Preach or teach one this year"]),
 S("Memorize Something","Scripture in your bones",["Psalm 119:11","Deuteronomy 6:6","Colossians 3:16"],["What is memorized is available at three in the morning","I have hidden your word in my heart","Let the word dwell in you richly"],"Father, write your Word in us.",["Memorize one verse this month","Say it to someone","Choose one you actually need"]),
 S("Reading as a Church","Same page, same week",["Nehemiah 8:1-3","Acts 2:42","1 Timothy 4:13"],["A church reading the same text is a different church","All the people assembled and Ezra read","Devote yourself to the public reading of Scripture"],"Lord, feed this whole church from your Word.",["Choose a churchwide reading plan","Align one series to it","Read one chapter aloud on Sunday"]),
 S("Study Tools","Three, not thirty",["2 Timothy 2:15","Proverbs 18:15","Acts 18:24-26"],["Tools serve the text; they do not replace it","The heart of the discerning acquires knowledge","Priscilla and Aquila explained more adequately"],"Father, help us study well.",["Learn one tool properly","Teach it to someone","Stop using one you do not understand"]),
 S("Teaching Adults","How grown-ups actually learn",["Nehemiah 8:8","Luke 24:27","Acts 8:30-31"],["Adults learn by discussing, not by receiving","They gave the meaning so people understood","How can I unless someone explains it"],"Lord, help us teach so people understand.",["Add one question to your next teaching","Stop talking five minutes early","Ask what was unclear"]),
 S("Where Christians Disagree","Handling contested texts",["Romans 14:1-12","Philippians 3:15-16","1 Corinthians 8:1-3"],["Mature Christians disagree and the church survives it","Accept the one whose faith is weak","Knowledge puffs up, love builds up"],"Father, give us humility about what we hold loosely.",["Name one thing you hold loosely","Read a fair case for the other view","Practise saying I might be wrong"]),
 S("The Whole Story","Reading it as one book",["Luke 24:27","Hebrews 1:1-2","2 Corinthians 1:20"],["Beginning with Moses he explained what was said about himself","All the promises are Yes in him","A verse read outside the story is a fragment"],"Lord, help us see the whole arc.",["Read one Old Testament book this quarter","Trace one theme across both testaments","Teach the arc once this year"]),
 S("Doers, Not Hearers","The point of all of it",["James 1:22-25","Matthew 7:24-27","Luke 6:46"],["Study that changes nothing has failed regardless of its depth","The one who looks and does not forget will be blessed","Why do you call me Lord and not do what I say"],"Father, make us doers.",["Obey one thing you already know","Name what you have been studying instead of doing","Tell someone what you will do"])]),

C("Worship & Wonder","Recovering awe in the people who run the service",
"The people who produce worship are the most likely in the building to stop experiencing it.",
["What song moves you most?","When did you last feel genuine awe?","What is your favourite place to worship?","What do you miss about worshipping as a participant?"],
["Lord, let us worship rather than produce. Restore wonder to people who handle holy things weekly.",
 "Father, you are worthy whether the service goes well or badly. Fix our eyes on you."],
["Psalm 95:1-7","Revelation 4:8-11","Isaiah 6:1-8","Romans 12:1","John 4:23-24"],
"Consider doing one of these as actual worship rather than discussion. Sing something. It is allowed.",
[S("Producing Instead of Worshipping","The occupational hazard",["Psalm 95:6","John 4:23-24","Luke 10:40-42"],["The people who build the service are least likely to receive it","Worship in spirit and truth","Martha was distracted by much serving"],"Lord, let us receive as well as give.",["Worship somewhere you have no role","Arrive early and pray rather than check","Sit down for one song"]),
 S("Holy, Holy, Holy","Recovering the fear of God",["Isaiah 6:1-8","Revelation 4:8-11","Psalm 96:9"],["Isaiah's response to holiness was ruin before commission","They never stop saying holy","Worship in the splendour of his holiness"],"Father, give us back our awe.",["Read Isaiah 6 slowly","Sit in silence after it","Name what you have grown casual about"]),
 S("Bodies in Worship","Standing, kneeling, raising",["Psalm 95:6","Romans 12:1","1 Timothy 2:8"],["Worship is physical before it is emotional","Come let us bow down and kneel","Offer your bodies as a living sacrifice"],"Lord, let our bodies say what our hearts mean.",["Change one posture this Sunday","Kneel once this week","Notice what your body is saying"]),
 S("The Songs We Sing","Theology at singing speed",["Colossians 3:16","Ephesians 5:19","Psalm 40:3"],["What we sing is what they will believe in ten years","Let the word of Christ dwell in you as you sing","He put a new song in my mouth"],"Father, let our songs be true.",["Read one setlist as theology","Cut one song that says nothing","Add one that says something hard"]),
 S("Wonder","The thing that goes first",["Psalm 8:3-4","Job 38:1-7","Psalm 19:1-4"],["Familiarity with holy things is the occupational risk","When I consider your heavens","The heavens declare the glory of God"],"Lord, restore our wonder.",["Go outside and look up","Read Job 38 aloud","Name one thing you stopped marvelling at"]),
 S("Lament as Worship","The songs we stopped singing",["Psalm 13","Psalm 88","Lamentations 3:19-24"],["A third of the psalms are laments and we sing almost none","How long, O Lord","Yet this I call to mind"],"Father, receive our sorrow as worship too.",["Read a lament psalm aloud","Include one lament this season","Let a hard song stay hard"]),
 S("Worship on a Tuesday","Beyond the service",["Romans 12:1","1 Corinthians 10:31","Colossians 3:23"],["Worship is a life offered, not an hour attended","Whatever you do, do it all for the glory of God","Work at it with all your heart"],"Lord, make our whole week an offering.",["Do one ordinary task as worship","Name where work and worship separated","Pray at the start of a task"]),
 S("The Table","Communion for the ones who serve it",["1 Corinthians 11:23-26","Luke 22:19-20","Acts 2:42"],["The people who serve the table often do not receive it","Do this in remembrance of me","They devoted themselves to the breaking of bread"],"Father, feed us at your table.",["Receive communion without serving","Take it slowly this week","Read 1 Corinthians 11 before Sunday"]),
 S("Silence in the Service","Making room",["Habakkuk 2:20","Psalm 46:10","1 Kings 19:12"],["Most services have no silence and most people have none anywhere","The Lord is in his holy temple, let all the earth be silent","A gentle whisper"],"Lord, teach us to be quiet before you.",["Add thirty seconds of silence Sunday","Practise it here","Resist filling the gap"]),
 S("Every Tribe and Tongue","The worship we are joining",["Revelation 7:9-10","Psalm 117","Philippians 2:9-11"],["Sunday joins something already in progress","A great multitude no one could count","Every knee will bow"],"Father, let us join what heaven is already doing.",["Sing one song in another language","Pray for the global church","Name who is missing from our room"])]),

C("Faith & Risk","Faith goals and the courage to name them",
"Most church plans are sized to the budget rather than to God, and everyone can tell which one they are looking at.",
["What is the biggest risk you ever took?","When did God come through unexpectedly?","What would you attempt if you knew you could not fail?","Who modelled faith for you?"],
["Lord, enlarge our faith. Keep us from small plans that need nothing from you.",
 "Father, we ask for more than we can manage and trust you with the difference."],
["Hebrews 11","Joshua 14:6-15","Ephesians 3:20-21","Matthew 17:20","2 Corinthians 5:7"],
"Do not let this become fantasy. Every idea named must get a real next step or the session teaches cynicism.",
[S("Faith Goals","Sized to God rather than the budget",["Ephesians 3:20","Joshua 14:12","1 Chronicles 4:10"],["A plan requiring nothing from God requires no faith","Give me this hill country","Jabez asked God to enlarge his territory"],"Father, give us goals that need you.",["Name one faith-sized goal","Write the number","Tell the team so it is real"]),
 S("Step Into the Water","Before it parts",["Joshua 3:13-16","Matthew 14:28-31","Exodus 14:15"],["The river parted when their feet touched it, not before","Peter walked because he got out","Tell the Israelites to move on"],"Lord, give us courage to move first.",["Take one step before you see the outcome","Name what you are waiting for","Do it this week"]),
 S("Counting the Cost and Going Anyway","Both are faithful",["Luke 14:28-33","Nehemiah 2:12-18","Numbers 13:30"],["Planning and faith are not opposites","Count the cost, then take up the cross","We should go up and take possession"],"Father, give us clear eyes and brave hearts.",["Cost one risk honestly","Name what could go wrong","Decide anyway"]),
 S("When It Failed","Faith after a loss",["Joshua 7:1-13","2 Corinthians 12:7-10","Acts 16:6-10"],["Failure is not always disobedience and is not always closed doors","Ai was a real defeat with a real cause","The Spirit prevented them, then redirected them"],"Lord, teach us in what did not work.",["Name one failure honestly","Ask what it taught","Try the next thing"]),
 S("The Ten and the Two","Why most reports are negative",["Numbers 13:26-33","Numbers 14:6-9","Hebrews 3:16-19"],["Ten saw giants and two saw the same giants","We seemed like grasshoppers in our own eyes","They could not enter because of unbelief"],"Father, give us eyes that see you in the report.",["Name one giant honestly","Name God honestly in the same sentence","Choose which report you give"]),
 S("Small Beginnings","Despising the day of small things",["Zechariah 4:10","Mark 4:30-32","1 Kings 18:44"],["The mustard seed is the smallest and becomes the largest","Who dares despise the day of small things","A cloud the size of a man's hand"],"Lord, help us honour small starts.",["Start one small thing","Celebrate a small win","Stop waiting for the big version"]),
 S("Obedience Without Clarity","Going before you understand",["Hebrews 11:8","Genesis 12:1-4","Acts 8:26-27"],["Abraham went without knowing where he was going","Go to the land I will show you","Philip got up and went to a desert road"],"Father, we will go before we understand.",["Obey one thing you do not fully understand","Name what you are waiting to be sure of","Take the step anyway"]),
 S("The Cost of Playing Safe","Burying the talent",["Matthew 25:24-30","Revelation 3:15-16","Proverbs 29:25"],["The servant who buried it was afraid and called it prudence","Neither hot nor cold","Fear of man is a snare"],"Lord, free us from safe faithlessness.",["Name where you have played safe","Take one risk this quarter","Ask what fear is driving it"]),
 S("Praying Bold Prayers","Asking for more",["Ephesians 3:20","1 Kings 18:36-38","James 4:2"],["We have not because we ask not","Answer me so these people will know","Immeasurably more than we ask or imagine"],"Father, we ask boldly and trust you with the answer.",["Pray one bold prayer out loud","Write it down and date it","Come back to it in a year"]),
 S("What Would We Attempt","The whole category in one question",["Ephesians 3:20-21","Joshua 14:12","Philippians 4:13"],["The constraint is often courage rather than capacity","Give me this mountain","I can do all things through him who strengthens me"],"Lord, give us one holy risk.",["Name one attempt","Assign one owner","Put a date on it"])]),

C("Perseverance & Endurance","Staying when it is hard",
"Most ministry is not dramatic. It is showing up in February for the ninth year, and nobody trains anyone for that.",
["What is the longest you have stuck at something?","Who has endured well in your life?","What keeps you going?","What almost made you quit?"],
["Lord, give us staying power. Let us not grow weary in doing good.",
 "Father, run with us the race marked out. Fix our eyes on Jesus."],
["Hebrews 12:1-3","Galatians 6:9","James 1:2-4","2 Corinthians 4:16-18","Romans 5:3-5"],
"Run these in late winter or after a hard stretch, when the answers are felt rather than theoretical.",
[S("Do Not Grow Weary","The verse for year nine",["Galatians 6:9","2 Thessalonians 3:13","1 Corinthians 15:58"],["At the proper time we will reap if we do not give up","Never tire of doing what is good","Your labour is not in vain"],"Lord, keep us going.",["Name what is wearing you down","Ask for help with one thing","Set one small marker to reach"]),
 S("The Long Obedience","Faithfulness over decades",["Hebrews 12:1-2","Psalm 92:12-14","2 Timothy 4:7"],["Run with perseverance the race marked out for us","They still bear fruit in old age","I have finished the race"],"Father, sustain us over years.",["Name someone who finished well","Ask them how","Choose one habit to keep for a decade"]),
 S("Suffering Produces","The chain Paul names",["Romans 5:3-5","James 1:2-4","1 Peter 1:6-7"],["Suffering produces perseverance, character, hope in that order","Consider it pure joy","Refined by fire, proved genuine"],"Lord, do not waste this.",["Name what a hard season produced","Thank God for one of them","Tell someone what you learned"]),
 S("When You Want to Quit","Naming it out loud",["1 Kings 19:4","Jeremiah 20:7-9","2 Corinthians 1:8-9"],["Elijah asked to die and God fed him","There is a fire in my bones and I cannot hold it in","We despaired of life itself"],"Father, meet us where we are ready to stop.",["Say it out loud to someone","Ask what you actually need","Rest before deciding"]),
 S("The Faithful Unnoticed","Ministry nobody sees",["Matthew 6:4","Colossians 3:23-24","Hebrews 6:10"],["God is not unjust; he will not forget your work","Your Father who sees in secret will reward you","You are serving the Lord Christ"],"Lord, we work for your eyes.",["Do one thing nobody will know about","Thank someone unseen","Stop needing the credit"]),
 S("Waiting","The season nobody chooses",["Psalm 27:14","Isaiah 40:31","Habakkuk 2:3"],["Waiting is a season, not a failure","They will renew their strength","Though it linger, wait for it"],"Father, teach us to wait well.",["Name what you are waiting for","Ask what to do while waiting","Stop forcing one thing"]),
 S("Finishing a Hard Year","Honest review",["2 Corinthians 4:16-18","Psalm 90:12","Lamentations 3:22-23"],["Outwardly wasting away, inwardly renewed day by day","Teach us to number our days","His mercies are new every morning"],"Lord, carry us to the end of this.",["Name what this year cost","Name what it gave","Mark the ending somehow"]),
 S("Encouragement","The fuel that runs out first",["Hebrews 3:13","1 Thessalonians 5:11","Acts 4:36"],["Encourage one another daily, as long as it is called today","Barnabas means son of encouragement","Build each other up"],"Father, make us encouragers.",["Encourage one person specifically","Do it in writing","Do it again next week"]),
 S("The Cloud of Witnesses","You are not the first",["Hebrews 12:1","Hebrews 11:32-40","2 Timothy 1:5"],["Surrounded by so great a cloud of witnesses","They were commended for their faith yet did not receive","Faith that first lived in your grandmother"],"Lord, thank you for those who went before.",["Name someone who ran before you","Read their story","Tell someone about them"]),
 S("Well Done","What we are running toward",["Matthew 25:21","2 Timothy 4:8","Revelation 2:10"],["Well done is the whole reward","There is a crown of righteousness","Be faithful unto death"],"Father, let us hear well done.",["Name what finishing looks like","Write it down","Keep it where you can see it"])]),
]
